import DateTimePicker from '@react-native-community/datetimepicker';
import * as Print from 'expo-print';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Svg, { Circle, Line, Path, Rect } from 'react-native-svg';
import { ActivityIndicator, Alert, Modal, Platform, Pressable, SafeAreaView, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { useEffect, useMemo, useState } from 'react';
import { materialApi, MaterialBootstrapResponse, MaterialLedgerRow, MaterialRecord, MaterialSummary, MaterialValues } from './api';
import { renderLedgerPdf } from './ledgerPdf';

type Tab = 'data' | 'summary' | 'ledger' | 'dashboard';
type OptionKind = 'supplier' | 'material';
type SupplierPositionView = 'chart' | 'breakdown';
const SUPPLIER_POSITION_VIEW_KEY = 'accurate_purchase_material_supplier_position_view';
type ThemeMode = 'light' | 'dark';
const lightC = { ink: '#14233b', muted: '#64748b', line: '#dfe7f1', canvas: '#f5f8fc', card: '#fff', blue: '#2563eb', blueSoft: '#eaf1ff', green: '#0f9d71', orange: '#ea580c', successSurface: '#f0fdf7', warningSurface: '#fff7ed', successBorder: '#b9ead7', warningBorder: '#fed7aa', paymentTrack: '#ffedd5', strongPanel: '#14233b', strongPanelMuted: '#b9c8dd', strongPanelText: '#ffffff' };
const darkC = { ink: '#f4f7fc', muted: '#aab8cc', line: '#293a54', canvas: '#0b1320', card: '#142238', blue: '#77a0ff', blueSoft: '#1c3157', green: '#34d399', orange: '#fb923c', successSurface: '#123c32', warningSurface: '#452a1b', successBorder: '#256b58', warningBorder: '#87451d', paymentTrack: '#3d2a20', strongPanel: '#1d304b', strongPanelMuted: '#b9c8dd', strongPanelText: '#ffffff' };
const c = { ...lightC };
let s: any;
let materialDark = false;
const applyMaterialTheme = (theme: ThemeMode) => { materialDark = theme === 'dark'; Object.assign(c, materialDark ? darkC : lightC); s = createMaterialStyles(); Object.assign(s, { materialPeriodCard: { backgroundColor: c.card, borderColor: c.line, borderWidth: 1, borderRadius: 16, padding: 14, marginBottom: 14 }, materialPeriodTitle: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start' }, materialClear: { color: c.blue, fontSize: 12, fontWeight: '900', backgroundColor: c.blueSoft, borderRadius: 12, paddingHorizontal: 9, paddingVertical: 4 }, materialDateFields: { flexDirection: 'row', flexWrap: 'wrap', gap: 10, marginTop: 10 }, materialDateField: { flexGrow: 1, flexBasis: 150 }, materialPeriodHint: { color: c.muted, fontSize: 12, marginTop: 10, lineHeight: 17 }, materialLedgerSummary: { backgroundColor: c.strongPanel, borderRadius: 16, padding: 16, marginBottom: 15 }, materialTotalGroup: { borderTopColor: 'rgba(255,255,255,0.16)', borderTopWidth: 1, marginTop: 13, paddingTop: 10 }, materialTotalTitle: { color: c.strongPanelText, fontSize: 13, fontWeight: '900' }, materialTotals: { flexDirection: 'row', flexWrap: 'wrap', gap: 12, marginTop: 8 }, materialMetric: { color: c.strongPanelText, fontSize: 12, fontWeight: '800' } }); };
const money = (v: unknown) => `₹${Number(v || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 })}`;
const show = (v: unknown) => v === '' || v === undefined || v === null ? '—' : String(v);
const dateOnly = (v: unknown) => { const raw = String(v || '').trim(); const found = raw.match(/^(\d{4})-(\d{2})-(\d{2})/); return found ? found[0] : raw.split(/[T\s]/)[0]; };
const inputDate = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const escapeHtml = (v: unknown) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

export default function MaterialWorkspace({ theme }: { theme: ThemeMode }) {
  applyMaterialTheme(theme);
  const [tab, setTab] = useState<Tab>('data');
  const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const [data, setData] = useState<MaterialBootstrapResponse | null>(null);
  const [ledgerSupplier, setLedgerSupplier] = useState(''); const [ledger, setLedger] = useState<MaterialLedgerRow[]>([]); const [ledgerLoading, setLedgerLoading] = useState(false);
  const [form, setForm] = useState<MaterialRecord | null>(null); const [saving, setSaving] = useState(false); const [exporting, setExporting] = useState<'one' | 'all' | null>(null);
  const load = async (withLoader = true) => { if (withLoader) setLoading(true); setError(''); try { const response = await materialApi.bootstrap(); setData(response); } catch (e) { setError(e instanceof Error ? e.message : 'Could not load Purchase Material.'); } finally { if (withLoader) setLoading(false); } };
  useEffect(() => { load(); }, []);
  useEffect(() => { let current = true; if (!ledgerSupplier) { setLedger([]); return; } setLedgerLoading(true); materialApi.getLedger(ledgerSupplier).then((rows) => { if (current) setLedger(rows); }).catch((e) => { if (current) Alert.alert('Could not load ledger', e instanceof Error ? e.message : 'Please try again.'); }).finally(() => { if (current) setLedgerLoading(false); }); return () => { current = false; }; }, [ledgerSupplier]);
  const save = async (values: MaterialValues) => { if (!values.date || !String(values.supplier || '').trim()) { Alert.alert('Date and supplier are required', 'Add both fields before saving.'); return false; } setSaving(true); try { const result = await materialApi.savePurchase(form?.sheetRow || 0, values); await load(false); setForm(null); Alert.alert('Saved to Google Sheets', `Purchase Material was saved in row ${result.sheetRow}.`); return true; } catch (e) { Alert.alert('Could not save', e instanceof Error ? e.message : 'Please try again.'); return false; } finally { setSaving(false); } };
  const addOption = async (kind: OptionKind, value: string) => { const clean = value.trim(); if (!clean) return; try { await materialApi.addOption(kind, clean); await load(false); } catch (e) { Alert.alert('Could not add option', e instanceof Error ? e.message : 'Please try again.'); throw e; } };
  const print = async (kind: 'one' | 'all', periodRows?: MaterialLedgerRow[], period?: string) => { if (kind === 'one' && (!ledgerSupplier || !periodRows?.length)) return; setExporting(kind); try { const groups = kind === 'one' ? [{ supplier: ledgerSupplier, rows: periodRows || [], overallRows: ledger, period: period || 'All dates' }] : (await materialApi.getAllLedgers()).map((group) => ({ ...group, overallRows: group.rows, period: 'All dates' })); if (!groups.length) throw new Error('No ledger entries are available.'); const html = materialPdf(groups); if (Platform.OS === 'web') { const w = window.open('', '_blank'); if (!w) throw new Error('Allow pop-ups to save the PDF.'); w.document.write(html); w.document.close(); setTimeout(() => w.print(), 300); } else { await Print.printAsync({ html }); } } catch (e) { Alert.alert('Could not create PDF', e instanceof Error ? e.message : 'Please try again.'); } finally { setExporting(null); } };
  if (loading) return <MaterialLoading />;
  if (error || !data) return <View style={s.error}><Text style={s.errorTitle}>Purchase Material is not connected</Text><Text style={s.errorCopy}>{error || 'No data returned.'}</Text><Pressable style={s.primary} onPress={() => load()}><Text style={s.primaryText}>Try again</Text></Pressable></View>;
  return <View style={s.root}><View style={s.body}>{tab === 'data' && <MaterialData records={data.records} suppliers={data.options.suppliers} onEdit={setForm} onNew={() => setForm({ sheetRow: 0, values: { date: inputDate(new Date()) } })} />}{tab === 'summary' && <MaterialSummaryView summary={data.summary} />}{tab === 'ledger' && <MaterialOverallLedger suppliers={data.options.suppliers} supplier={ledgerSupplier} onSupplier={setLedgerSupplier} rows={ledger} loading={ledgerLoading} exporting={exporting} onPrint={print} />}{tab === 'dashboard' && <MaterialDashboard summary={data.dashboard} />}</View><MaterialNav active={tab} onChange={setTab} /><MaterialForm record={form} visible={!!form} suppliers={data.options.suppliers} materials={data.options.materials} saving={saving} onClose={() => setForm(null)} onSave={save} onAddOption={addOption} /></View>;
}

function MaterialLoading() { return <View style={s.loader}><View style={s.sheetMark}><Text style={s.sheetMarkText}>▦</Text></View><Text style={s.eyebrow}>PURCHASE MATERIAL</Text><Text style={s.loaderTitle}>Opening your material sheet</Text><Text style={s.loaderCopy}>Reading purchases, suppliers, and formula totals</Text><View style={s.loaderDots}><View style={s.dotActive} /><View style={s.dot} /><View style={s.dot} /></View></View>; }

function MaterialData({ records, suppliers, onEdit, onNew }: { records: MaterialRecord[]; suppliers: string[]; onEdit: (r: MaterialRecord) => void; onNew: () => void }) {
  const [supplier, setSupplier] = useState(''); const [order, setOrder] = useState<'latest' | 'oldest'>('latest');
  const rows = useMemo(() => records.filter((r) => !supplier || r.values.supplier === supplier).sort((a, b) => { const diff = new Date(String(a.values.date || 0)).getTime() - new Date(String(b.values.date || 0)).getTime(); return order === 'latest' ? -diff : diff; }), [records, supplier, order]);
  return <ScrollView contentContainerStyle={s.scroll}><View style={s.heading}><View><Text style={s.sectionTitle}>Purchase data</Text><Text style={s.sub}>Tap an entry to edit it in Google Sheets.</Text></View><Pressable style={s.add} onPress={onNew}><Text style={s.addText}>＋ Add record</Text></Pressable></View><View style={s.controls}><Select label="Supplier filter" value={supplier || 'All suppliers'} options={['', ...suppliers]} onChange={setSupplier} /><View style={s.sortBox}><Text style={s.controlLabel}>Date order</Text><View style={s.sortButtons}><Pressable style={[s.sort, order === 'latest' && s.sortActive]} onPress={() => setOrder('latest')}><Text style={[s.sortText, order === 'latest' && s.sortTextActive]}>Latest</Text></Pressable><Pressable style={[s.sort, order === 'oldest' && s.sortActive]} onPress={() => setOrder('oldest')}><Text style={[s.sortText, order === 'oldest' && s.sortTextActive]}>Oldest</Text></Pressable></View></View></View><Text style={s.recordCount}>{rows.length} record{rows.length === 1 ? '' : 's'}</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.tableCard}><View style={{ width: 985 }}><View style={[s.tableRow, s.tableHeader]}>{['Date', 'Supplier', 'Bill no.', 'Material', 'Bill amount', 'Without bill', 'Bill paid', 'Without paid', 'Total paid'].map((h, i) => <Text key={h} style={[s.cell, s.headerCell, { width: i === 1 ? 150 : i === 3 ? 120 : 105 }]}>{h}</Text>)}</View><ScrollView style={{ maxHeight: 476 }} nestedScrollEnabled showsVerticalScrollIndicator>{rows.map((record) => <Pressable key={record.sheetRow} style={({ pressed }) => [s.tableRow, pressed && s.pressed]} onPress={() => onEdit(record)}><Text style={[s.cell, { width: 105 }]}>{dateOnly(record.values.date)}</Text><Text style={[s.cell, { width: 150 }]}>{show(record.values.supplier)}</Text><Text style={[s.cell, { width: 105 }]}>{show(record.values.billNo)}</Text><Text style={[s.cell, { width: 120 }]}>{show(record.values.material)}</Text><Text style={[s.cell, { width: 105 }]}>{money(record.values.billAmount)}</Text><Text style={[s.cell, { width: 105 }]}>{money(record.values.withoutBillAmount)}</Text><Text style={[s.cell, { width: 105 }]}>{money(record.values.billPaid)}</Text><Text style={[s.cell, { width: 105 }]}>{money(record.values.withoutPaid)}</Text><Text style={[s.cell, s.strongCell, { width: 105 }]}>{money(record.values.totalPaid)}</Text></Pressable>)}</ScrollView></View></ScrollView></ScrollView>;
}

function MaterialSummaryView({ summary }: { summary: MaterialSummary }) { return <ScrollView contentContainerStyle={s.scroll}><Text style={s.sectionTitle}>Purchase summary</Text><Text style={s.sub}>Totals and supplier outstanding directly from the Purchase Summary sheet.</Text><View style={s.kpiGrid}><Kpi label="Total purchase" value={money(summary.totalPurchase)} /><Kpi label="Total paid" value={money(summary.totalPaid)} accent="green" /><Kpi label="Outstanding" value={money(summary.totalOutstanding)} accent="orange" /></View><Text style={s.tableTitle}>Supplier outstanding</Text><SummaryTable suppliers={summary.suppliers} /></ScrollView>; }

function MaterialDashboard({ summary }: { summary: MaterialSummary }) {
  const [supplierView, setSupplierView] = useState<SupplierPositionView>('chart');
  const topOutstanding = [...summary.suppliers].sort((a, b) => b.outstanding - a.outstanding)[0];
  useEffect(() => { let active = true; AsyncStorage.getItem(SUPPLIER_POSITION_VIEW_KEY).then((value) => { if (active && (value === 'chart' || value === 'breakdown')) setSupplierView(value); }).catch(() => {}); return () => { active = false; }; }, []);
  const changeSupplierView = (view: SupplierPositionView) => { setSupplierView(view); AsyncStorage.setItem(SUPPLIER_POSITION_VIEW_KEY, view).catch(() => {}); };
  return <ScrollView contentContainerStyle={s.scroll}>
    <Text style={s.sectionTitle}>Purchase dashboard</Text>
    <Text style={s.sub}>Formula-backed totals with scalable supplier analytics.</Text>
    <View style={s.kpiGrid}><Kpi label="Total purchase" value={money(summary.totalPurchase)} /><Kpi label="Total paid" value={money(summary.totalPaid)} accent="green" /><Kpi label="Outstanding" value={money(summary.totalOutstanding)} accent="orange" /></View>
    {topOutstanding ? <View style={[s.chartCard, { marginTop: 0, backgroundColor: c.warningSurface, borderColor: c.warningBorder }]}><Text style={s.tableTitle}>Largest payment exposure</Text><Text style={s.chartHint}>Supplier requiring the most payment attention</Text><View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 12, alignItems: 'flex-end' }}><View style={{ flex: 1 }}><Text style={{ color: c.ink, fontSize: 16, fontWeight: '900' }}>{topOutstanding.supplier}</Text><Text style={{ color: c.muted, fontSize: 12, marginTop: 4 }}>Outstanding from the Purchase Summary sheet</Text></View><Text style={{ color: c.orange, fontSize: 22, fontWeight: '900' }}>{money(topOutstanding.outstanding)}</Text></View></View> : null}
    <SupplierPaymentPosition rows={summary.suppliers} view={supplierView} onChange={changeSupplierView} />
    <PaymentHealthRing totalPurchase={summary.totalPurchase} totalPaid={summary.totalPaid} totalOutstanding={summary.totalOutstanding} />
  </ScrollView>;
}

function SupplierPaymentPosition({ rows, view, onChange }: { rows: MaterialSummary['suppliers']; view: SupplierPositionView; onChange: (view: SupplierPositionView) => void }) {
  const visible = [...rows].sort((a, b) => b.purchase - a.purchase).slice(0, 6);
  const maximum = Math.max(1, ...visible.map((row) => row.purchase));
  return <View style={s.chartCard}>
    <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 10, alignItems: 'flex-start' }}><View style={{ flex: 1 }}><Text style={s.tableTitle}>Supplier payment position</Text><Text style={s.chartHint}>{view === 'chart' ? 'Top suppliers by purchase · paid versus outstanding' : 'A compact numerical breakdown for each supplier'}</Text></View></View>
    <View style={{ flexDirection: 'row', borderRadius: 11, backgroundColor: c.blueSoft, padding: 3, marginBottom: 15 }}>
      <Pressable onPress={() => onChange('chart')} style={{ flex: 1, minHeight: 38, borderRadius: 8, alignItems: 'center', justifyContent: 'center', backgroundColor: view === 'chart' ? c.blue : 'transparent' }}><Text style={{ color: view === 'chart' ? '#fff' : c.muted, fontSize: 12, fontWeight: '900' }}>▤ Chart</Text></Pressable>
      <Pressable onPress={() => onChange('breakdown')} style={{ flex: 1, minHeight: 38, borderRadius: 8, alignItems: 'center', justifyContent: 'center', backgroundColor: view === 'breakdown' ? c.blue : 'transparent' }}><Text style={{ color: view === 'breakdown' ? '#fff' : c.muted, fontSize: 12, fontWeight: '900' }}>≡ Breakdown</Text></Pressable>
    </View>
    {view === 'chart' ? <><View style={{ flexDirection: 'row', gap: 16, marginBottom: 13 }}><Text style={{ color: c.green, fontSize: 11, fontWeight: '900' }}>● Paid</Text><Text style={{ color: c.orange, fontSize: 11, fontWeight: '900' }}>● Outstanding</Text></View>{visible.length ? visible.map((row) => { const totalWidth = Math.max(4, (row.purchase / maximum) * 100); const settledBase = row.paid + row.outstanding; const paidShare = settledBase ? Math.max(0, Math.min(100, (row.paid / settledBase) * 100)) : 0; return <View key={row.supplier} style={{ marginBottom: 17 }}><View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 10, marginBottom: 7 }}><Text numberOfLines={1} style={{ flex: 1, color: c.ink, fontSize: 13, fontWeight: '900' }}>{row.supplier}</Text><Text style={{ color: c.ink, fontSize: 13, fontWeight: '900' }}>{money(row.purchase)}</Text></View><View style={{ height: 14, backgroundColor: '#edf2f7', borderRadius: 99, overflow: 'hidden' }}><View style={{ width: (String(totalWidth) + '%') as any, height: '100%', backgroundColor: c.orange, borderRadius: 99, overflow: 'hidden' }}><View style={{ width: (String(paidShare) + '%') as any, height: '100%', backgroundColor: c.green, borderRadius: 99 }} /></View></View><View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: 6, gap: 10 }}><Text style={{ color: c.green, fontSize: 11, fontWeight: '800' }}>Paid {money(row.paid)}</Text><Text style={{ color: c.orange, fontSize: 11, fontWeight: '800' }}>Due {money(row.outstanding)}</Text></View></View>; }) : <Text style={s.chartHint}>No supplier data is currently available.</Text>}</> : <SupplierBreakdown rows={visible} />}
    {rows.length > visible.length ? <Text style={{ color: c.muted, fontSize: 11, textAlign: 'center', marginTop: 2 }}>Showing top {visible.length} of {rows.length} suppliers. View Summary for the complete table.</Text> : null}
  </View>;
}

function SupplierBreakdown({ rows }: { rows: MaterialSummary['suppliers'] }) {
  return <View style={{ gap: 8 }}>{rows.length ? rows.map((row, index) => <View key={row.supplier} style={{ backgroundColor: c.card, borderWidth: 1, borderColor: c.line, borderRadius: 12, padding: 11, flexDirection: 'row', alignItems: 'center', gap: 9 }}><View style={{ width: 25, height: 25, borderRadius: 99, backgroundColor: c.blueSoft, alignItems: 'center', justifyContent: 'center' }}><Text style={{ color: c.blue, fontSize: 11, fontWeight: '900' }}>{index + 1}</Text></View><View style={{ flex: 1, minWidth: 72 }}><Text numberOfLines={1} style={{ color: c.ink, fontSize: 12, fontWeight: '900' }}>{row.supplier}</Text><Text style={{ color: c.blue, fontSize: 11, fontWeight: '800', marginTop: 3 }}>{money(row.purchase)}</Text></View><View style={{ alignItems: 'flex-end' }}><Text style={{ color: c.green, fontSize: 10, fontWeight: '800' }}>PAID</Text><Text style={{ color: c.ink, fontSize: 12, fontWeight: '900', marginTop: 2 }}>{money(row.paid)}</Text></View><View style={{ alignItems: 'flex-end' }}><Text style={{ color: c.orange, fontSize: 10, fontWeight: '800' }}>DUE</Text><Text style={{ color: c.orange, fontSize: 12, fontWeight: '900', marginTop: 2 }}>{money(row.outstanding)}</Text></View></View>) : <Text style={s.chartHint}>No supplier data is currently available.</Text>}</View>;
}

function PaymentHealthRing({ totalPurchase, totalPaid, totalOutstanding }: { totalPurchase: number; totalPaid: number; totalOutstanding: number }) {
  const ratio = totalPurchase ? Math.max(0, Math.min(1, totalPaid / totalPurchase)) : 0;
  const radius = 54; const circumference = 2 * Math.PI * radius; const paidLength = ratio * circumference;
  return <View style={s.chartCard}><Text style={s.tableTitle}>Overall payment health</Text><Text style={s.chartHint}>A stable two-part view, independent of supplier count</Text><View style={{ flexDirection: 'row', alignItems: 'center', flexWrap: 'wrap', gap: 18 }}><View style={{ width: 142, height: 142, alignItems: 'center', justifyContent: 'center' }}><Svg width={142} height={142} viewBox="0 0 142 142"><Circle cx="71" cy="71" r={radius} fill="none" stroke={c.paymentTrack} strokeWidth="18" /><Circle cx="71" cy="71" r={radius} fill="none" stroke={c.green} strokeWidth="18" strokeLinecap="round" strokeDasharray={String(paidLength) + ' ' + String(circumference)} transform="rotate(-90 71 71)" /></Svg><View style={{ position: 'absolute', alignItems: 'center' }}><Text style={{ color: c.ink, fontSize: 22, fontWeight: '900' }}>{Math.round(ratio * 100)}%</Text><Text style={{ color: c.muted, fontSize: 10, marginTop: 2 }}>paid</Text></View></View><View style={{ flex: 1, minWidth: 150, gap: 12 }}><View style={{ padding: 11, backgroundColor: c.successSurface, borderRadius: 12 }}><Text style={{ color: c.green, fontSize: 11, fontWeight: '800' }}>● PAID</Text><Text style={{ color: c.ink, fontSize: 17, fontWeight: '900', marginTop: 4 }}>{money(totalPaid)}</Text></View><View style={{ padding: 11, backgroundColor: c.warningSurface, borderRadius: 12 }}><Text style={{ color: c.orange, fontSize: 11, fontWeight: '800' }}>● OUTSTANDING</Text><Text style={{ color: c.ink, fontSize: 17, fontWeight: '900', marginTop: 4 }}>{money(totalOutstanding)}</Text></View></View></View></View>;
}

function MaterialLedger({ suppliers, supplier, onSupplier, rows, loading, exporting, onPrint }: { suppliers: string[]; supplier: string; onSupplier: (x: string) => void; rows: MaterialLedgerRow[]; loading: boolean; exporting: 'one' | 'all' | null; onPrint: (x: 'one' | 'all') => void }) { const [dateOrder, setDateOrder] = useState<'sheet' | 'latest' | 'oldest'>('sheet'); const closing = rows[rows.length - 1]?.runningOutstanding; const displayRows = dateOrder === 'sheet' ? rows : [...rows].sort((a, b) => { const diff = new Date(dateOnly(a.date)).getTime() - new Date(dateOnly(b.date)).getTime(); return dateOrder === 'latest' ? -diff : diff; }); return <ScrollView contentContainerStyle={s.scroll}><Text style={s.sectionTitle}>Party ledger</Text><Text style={s.sub}>Running outstanding is calculated by the Party Ledger sheet.</Text><Select compact label="Select supplier" value={supplier} options={suppliers} onChange={onSupplier} /><View style={{ marginBottom: 14 }}><Text style={s.controlLabel}>Date order</Text><View style={s.sortButtons}><Pressable style={[s.sort, dateOrder === 'sheet' && s.sortActive]} onPress={() => setDateOrder('sheet')}><Text style={[s.sortText, dateOrder === 'sheet' && s.sortTextActive]}>Sheet order</Text></Pressable><Pressable style={[s.sort, dateOrder === 'latest' && s.sortActive]} onPress={() => setDateOrder('latest')}><Text style={[s.sortText, dateOrder === 'latest' && s.sortTextActive]}>Latest</Text></Pressable><Pressable style={[s.sort, dateOrder === 'oldest' && s.sortActive]} onPress={() => setDateOrder('oldest')}><Text style={[s.sortText, dateOrder === 'oldest' && s.sortTextActive]}>Oldest</Text></Pressable></View></View><View style={s.pdfActions}><Pressable disabled={!supplier || !!exporting} style={[s.primary, (!supplier || exporting) && s.disabled]} onPress={() => onPrint('one')}><Text style={s.primaryText}>{exporting === 'one' ? 'Preparing PDF…' : '⇩ Selected PDF'}</Text></Pressable><Pressable disabled={!!exporting} style={[s.secondary, exporting && s.disabled]} onPress={() => onPrint('all')}><Text style={s.secondaryText}>{exporting === 'all' ? 'Preparing…' : '⇩ All ledgers'}</Text></Pressable></View>{loading ? <View style={s.ledgerLoad}><ActivityIndicator color={c.blue} /><Text style={s.sub}>Loading supplier ledger…</Text></View> : <><View style={s.closing}><Text style={s.closingLabel}>Closing running outstanding</Text><Text style={s.closingValue}>{closing === undefined ? '—' : money(closing)}</Text><Text style={s.closingNote}>{rows.length} formula-based ledger entry{rows.length === 1 ? '' : 'ies'}</Text></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.tableCard}><View><View style={[s.tableRow, s.tableHeader]}>{['Date', 'Bill no.', 'Bill amount', 'Without bill', 'Total purchase', 'Total paid', 'Running outstanding'].map((h) => <Text key={h} style={[s.cell, s.headerCell, { width: 120 }]}>{h}</Text>)}</View>{displayRows.map((row, i) => <View key={`${row.date}-${i}`} style={s.tableRow}><Text style={[s.cell, { width: 120 }]}>{dateOnly(row.date)}</Text><Text style={[s.cell, { width: 120 }]}>{show(row.billNo)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.billAmount)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.withoutBill)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.totalPurchase)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.totalPaid)}</Text><Text style={[s.cell, s.strongCell, { width: 120 }]}>{money(row.runningOutstanding)}</Text></View>)}</View></ScrollView></>}</ScrollView>; }

type MaterialLedgerDateMode = 'single' | 'range';
const materialPeriodLabel = (mode: MaterialLedgerDateMode | null, start: string, end: string) => mode === null ? 'All dates' : mode === 'single' ? start : `${start} to ${end}`;
// A date filter only hides rows; it keeps the running balance fetched for each original row.
const filterMaterialLedger = (rows: MaterialLedgerRow[], mode: MaterialLedgerDateMode | null, start: string, end: string) => !mode ? rows : rows.filter((row) => { const date = dateOnly(row.date); if (mode === 'single') return !!start && date === start; if (!start || !end) return true; return date >= (start <= end ? start : end) && date <= (start <= end ? end : start); });
function MaterialDateFilteredLedger({ suppliers, supplier, onSupplier, rows, loading, exporting, onPrint }: { suppliers: string[]; supplier: string; onSupplier: (x: string) => void; rows: MaterialLedgerRow[]; loading: boolean; exporting: 'one' | 'all' | null; onPrint: (kind: 'one' | 'all', periodRows?: MaterialLedgerRow[], period?: string) => void }) { const [mode, setMode] = useState<MaterialLedgerDateMode | null>(null); const [start, setStart] = useState(''); const [end, setEnd] = useState(''); const activePeriod = mode === null || (mode === 'single' ? !!start : !!start && !!end); const periodRows = useMemo(() => filterMaterialLedger(rows, mode, start, end).sort((a, b) => dateOnly(a.date).localeCompare(dateOnly(b.date))), [rows, mode, start, end]); const totals = (items: MaterialLedgerRow[]) => items.reduce((total, row) => ({ purchase: total.purchase + Number(row.totalPurchase || 0), paid: total.paid + Number(row.totalPaid || 0) }), { purchase: 0, paid: 0 }); const overall = totals(rows); const perPeriod = totals(periodRows); const periodOutstanding = perPeriod.purchase - perPeriod.paid; const overallOutstanding = overall.purchase - overall.paid; const clear = () => { setMode(null); setStart(''); setEnd(''); }; const selectMode = (next: MaterialLedgerDateMode) => { setMode(next); if (next === 'single') setEnd(''); }; return <ScrollView contentContainerStyle={s.scroll}><Text style={s.sectionTitle}>Party ledger</Text><Text style={s.sub}>Purchase, paid, and outstanding are shown for both the selected period and all dates.</Text><Select compact label="Select supplier" value={supplier} options={suppliers} onChange={onSupplier} /><View style={s.materialPeriodCard}><View style={s.materialPeriodTitle}><Text style={s.controlLabel}>Ledger period</Text>{mode ? <Pressable onPress={clear}><Text style={s.materialClear}>× Clear</Text></Pressable> : null}</View><View style={s.sortButtons}><Pressable style={[s.sort, mode === 'single' && s.sortActive]} onPress={() => selectMode('single')}><Text style={[s.sortText, mode === 'single' && s.sortTextActive]}>Single day</Text></Pressable><Pressable style={[s.sort, mode === 'range' && s.sortActive]} onPress={() => selectMode('range')}><Text style={[s.sortText, mode === 'range' && s.sortTextActive]}>Multiple days</Text></Pressable></View><View style={s.materialDateFields}><View style={s.materialDateField}><Text style={s.controlLabel}>{mode === 'single' ? 'Select date' : 'From date'}</Text><TextInput style={s.input} value={start} onChangeText={setStart} placeholder="YYYY-MM-DD" placeholderTextColor={c.muted} /></View>{mode === 'range' ? <View style={s.materialDateField}><Text style={s.controlLabel}>To date</Text><TextInput style={s.input} value={end} onChangeText={setEnd} placeholder="YYYY-MM-DD" placeholderTextColor={c.muted} /></View> : null}</View><Text style={s.materialPeriodHint}>{mode === null ? 'Showing all entries. Choose dates only when you need a filtered ledger.' : activePeriod ? `Showing ${materialPeriodLabel(mode, start, end)}` : 'Choose the required date or date range.'}</Text></View><View style={s.pdfActions}><Pressable disabled={!supplier || !activePeriod || !periodRows.length || !!exporting || loading} style={[s.primary, (!supplier || !activePeriod || !periodRows.length || exporting || loading) && s.disabled]} onPress={() => onPrint('one', periodRows, materialPeriodLabel(mode, start, end))}><Text style={s.primaryText}>{exporting === 'one' ? 'Preparing PDF…' : '⇩ Download ledger PDF'}</Text></Pressable><Pressable disabled={!!exporting || loading} style={[s.secondary, (exporting || loading) && s.disabled]} onPress={() => onPrint('all')}><Text style={s.secondaryText}>{exporting === 'all' ? 'Preparing…' : '⇩ All ledgers'}</Text></Pressable></View>{loading ? <View style={s.ledgerLoad}><ActivityIndicator color={c.blue} /><Text style={s.sub}>Loading supplier ledger…</Text></View> : supplier ? <><View style={s.materialLedgerSummary}><Text style={s.closingLabel}>{supplier}</Text><View style={s.materialTotalGroup}><Text style={s.materialTotalTitle}>Overall</Text><View style={s.materialTotals}><Text style={s.materialMetric}>Purchase {money(overall.purchase)}</Text><Text style={s.materialMetric}>Paid {money(overall.paid)}</Text><Text style={[s.materialMetric, { color: overallOutstanding > 0 ? '#FFB4B4' : '#9BE7C7' }]}>Outstanding {money(overallOutstanding)}</Text></View></View><View style={s.materialTotalGroup}><Text style={s.materialTotalTitle}>Per period · {materialPeriodLabel(mode, start, end)}</Text><View style={s.materialTotals}><Text style={s.materialMetric}>Purchase {money(perPeriod.purchase)}</Text><Text style={s.materialMetric}>Paid {money(perPeriod.paid)}</Text><Text style={[s.materialMetric, { color: periodOutstanding > 0 ? '#FFB4B4' : '#9BE7C7' }]}>Outstanding {money(periodOutstanding)}</Text></View></View></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.tableCard}><View><View style={[s.tableRow, s.tableHeader]}>{['Date', 'Bill no.', 'Bill amount', 'Without bill', 'Total purchase', 'Total paid', 'Running outstanding'].map((h) => <Text key={h} style={[s.cell, s.headerCell, { width: 120 }]}>{h}</Text>)}</View>{periodRows.length ? periodRows.map((row, i) => <View key={`${row.date}-${i}`} style={s.tableRow}><Text style={[s.cell, { width: 120 }]}>{dateOnly(row.date)}</Text><Text style={[s.cell, { width: 120 }]}>{show(row.billNo)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.billAmount)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.withoutBill)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.totalPurchase)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.totalPaid)}</Text><Text style={[s.cell, s.strongCell, { width: 120 }]}>{money(row.runningOutstanding)}</Text></View>) : <Text style={s.emptyText}>No transactions found for this period.</Text>}</View></ScrollView></> : <View style={s.ledgerLoad}><Text style={s.sub}>Select a supplier to view its ledger.</Text></View>}</ScrollView>; }

function MaterialOverallLedger({ suppliers, supplier, onSupplier, rows, loading, exporting, onPrint }: { suppliers: string[]; supplier: string; onSupplier: (x: string) => void; rows: MaterialLedgerRow[]; loading: boolean; exporting: 'one' | 'all' | null; onPrint: (kind: 'one' | 'all', periodRows?: MaterialLedgerRow[], period?: string) => void }) {
  const [mode, setMode] = useState<MaterialLedgerDateMode | null>(null); const [start, setStart] = useState(''); const [end, setEnd] = useState('');
  const ready = mode === null || (mode === 'single' ? !!start : !!start && !!end); const visibleRows = useMemo(() => filterMaterialLedger(rows, mode, start, end).sort((a, b) => dateOnly(a.date).localeCompare(dateOnly(b.date))), [rows, mode, start, end]);
  const overall = rows.reduce((total, row) => ({ purchase: total.purchase + Number(row.totalPurchase || 0), paid: total.paid + Number(row.totalPaid || 0) }), { purchase: 0, paid: 0 }); const outstanding = rows[rows.length - 1]?.runningOutstanding || 0;
  const clear = () => { setMode(null); setStart(''); setEnd(''); }; const choose = (next: MaterialLedgerDateMode) => { setMode(next); if (next === 'single') setEnd(''); };
  return <ScrollView contentContainerStyle={s.scroll}><Text style={s.sectionTitle}>Party ledger</Text><Text style={s.sub}>Date selection only filters the displayed rows; running outstanding stays unchanged.</Text><Select compact label="Select supplier" value={supplier} options={suppliers} onChange={onSupplier} /><View style={s.materialPeriodCard}><View style={s.materialPeriodTitle}><Text style={s.controlLabel}>Ledger period</Text>{mode ? <Pressable onPress={clear}><Text style={s.materialClear}>× Clear</Text></Pressable> : null}</View><View style={s.sortButtons}><Pressable style={[s.sort, mode === 'single' && s.sortActive]} onPress={() => choose('single')}><Text style={[s.sortText, mode === 'single' && s.sortTextActive]}>Single day</Text></Pressable><Pressable style={[s.sort, mode === 'range' && s.sortActive]} onPress={() => choose('range')}><Text style={[s.sortText, mode === 'range' && s.sortTextActive]}>Multiple days</Text></Pressable></View><View style={s.materialDateFields}><MaterialLedgerDateField label={mode === 'single' ? 'Select date' : 'From date'} value={start} onChange={setStart} />{mode === 'range' ? <MaterialLedgerDateField label="To date" value={end} onChange={setEnd} /> : null}</View><Text style={s.materialPeriodHint}>{mode === null ? 'Showing all entries.' : ready ? `Showing ${materialPeriodLabel(mode, start, end)}` : 'Choose the required date or date range.'}</Text></View><View style={s.pdfActions}><Pressable disabled={!supplier || !ready || !visibleRows.length || !!exporting || loading} style={[s.primary, (!supplier || !ready || !visibleRows.length || exporting || loading) && s.disabled]} onPress={() => onPrint('one', visibleRows, materialPeriodLabel(mode, start, end))}><Text style={s.primaryText}>{exporting === 'one' ? 'Preparing PDF…' : '⇩ Download ledger PDF'}</Text></Pressable><Pressable disabled={!!exporting || loading} style={[s.secondary, (exporting || loading) && s.disabled]} onPress={() => onPrint('all')}><Text style={s.secondaryText}>{exporting === 'all' ? 'Preparing…' : '⇩ All ledgers'}</Text></Pressable></View>{loading ? <View style={s.ledgerLoad}><ActivityIndicator color={c.blue} /></View> : supplier ? <><View style={s.materialLedgerSummary}><Text style={s.closingLabel}>{supplier}</Text><View style={s.materialTotalGroup}><Text style={s.materialTotalTitle}>Overall</Text><View style={s.materialTotals}><Text style={s.materialMetric}>Purchase {money(overall.purchase)}</Text><Text style={s.materialMetric}>Paid {money(overall.paid)}</Text><Text style={[s.materialMetric, { color: outstanding > 0 ? '#FFB4B4' : '#9BE7C7' }]}>Outstanding {money(outstanding)}</Text></View></View></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.tableCard}><View><View style={[s.tableRow, s.tableHeader]}>{['Date', 'Bill no.', 'Bill amount', 'Without bill', 'Total purchase', 'Total paid', 'Running outstanding'].map((h) => <Text key={h} style={[s.cell, s.headerCell, { width: 120 }]}>{h}</Text>)}</View>{visibleRows.length ? visibleRows.map((row, i) => <View key={`${row.date}-${i}`} style={s.tableRow}><Text style={[s.cell, { width: 120 }]}>{dateOnly(row.date)}</Text><Text style={[s.cell, { width: 120 }]}>{show(row.billNo)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.billAmount)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.withoutBill)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.totalPurchase)}</Text><Text style={[s.cell, { width: 120 }]}>{money(row.totalPaid)}</Text><Text style={[s.cell, s.strongCell, { width: 120 }]}>{money(row.runningOutstanding)}</Text></View>) : <Text style={s.emptyText}>No transactions found for this period.</Text>}</View></ScrollView></> : <View style={s.ledgerLoad}><Text style={s.sub}>Select a supplier to view its ledger.</Text></View>}</ScrollView>;
}

function MaterialLedgerDateField({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { const [open, setOpen] = useState(false); if (Platform.OS === 'web') return <View style={s.materialDateField}><Text style={s.controlLabel}>{label}</Text><TextInput style={s.input} value={value} onChangeText={onChange} placeholder="YYYY-MM-DD" placeholderTextColor={c.muted} {...({ type: 'date' } as any)} /></View>; return <View style={s.materialDateField}><Text style={s.controlLabel}>{label}</Text><Pressable style={s.input} onPress={() => setOpen(true)}><Text style={s.inputText}>{value || 'Select date'}</Text></Pressable>{open ? <Modal transparent animationType="fade" onRequestClose={() => setOpen(false)}><View style={s.overlay}><View style={s.datePicker}><DateTimePicker value={new Date(`${value || inputDate(new Date())}T12:00:00`)} mode="date" display={Platform.OS === 'ios' ? 'inline' : 'calendar'} onChange={(_, date) => { if (date) onChange(inputDate(date)); if (Platform.OS !== 'ios') setOpen(false); }} /><Pressable style={s.primary} onPress={() => setOpen(false)}><Text style={s.primaryText}>Done</Text></Pressable></View></View></Modal> : null}</View>; }

function Kpi({ label, value, accent }: { label: string; value: string; accent?: 'green' | 'orange' }) { return <View style={[s.kpi, accent === 'green' && s.kpiGreen, accent === 'orange' && s.kpiOrange]}><Text style={s.kpiLabel}>{label}</Text><Text style={s.kpiValue}>{value}</Text></View>; }
function SummaryTable({ suppliers }: { suppliers: MaterialSummary['suppliers'] }) { return <ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.tableCard}><View><View style={[s.tableRow, s.tableHeader]}>{['Supplier', 'Purchase', 'Paid', 'Outstanding'].map((x, i) => <Text key={x} style={[s.cell, s.headerCell, { width: i ? 125 : 170 }]}>{x}</Text>)}</View>{suppliers.map((row) => <View key={row.supplier} style={s.tableRow}><Text style={[s.cell, s.strongCell, { width: 170 }]}>{row.supplier}</Text><Text style={[s.cell, { width: 125 }]}>{money(row.purchase)}</Text><Text style={[s.cell, { width: 125 }]}>{money(row.paid)}</Text><Text style={[s.cell, s.orangeText, { width: 125 }]}>{money(row.outstanding)}</Text></View>)}</View></ScrollView>; }
function Select({ label, value, options, onChange, compact = false }: { label: string; value: string; options: string[]; onChange: (value: string) => void; compact?: boolean }) { const [open, setOpen] = useState(false); const [query, setQuery] = useState(''); const visible = options.filter((x) => x.toLowerCase().includes(query.toLowerCase())); return <View style={[s.selectWrap, compact && { flexGrow: 0, flexBasis: 'auto' }]}><Text style={s.controlLabel}>{label}</Text><Pressable style={s.select} onPress={() => { setQuery(''); setOpen(true); }}><Text numberOfLines={1} style={s.selectText}>{value || 'Select'}</Text><Text style={s.chevron}>⌄</Text></Pressable><Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}><Pressable style={s.overlay} onPress={() => setOpen(false)}><Pressable style={s.picker} onPress={(e) => e.stopPropagation()}><Text style={s.pickerTitle}>{label}</Text><TextInput value={query} onChangeText={setQuery} placeholder="Search…" placeholderTextColor={c.muted} style={s.search} autoFocus />{visible.length ? <ScrollView style={s.options}>{visible.map((item) => <Pressable key={item || '__all'} style={s.option} onPress={() => { onChange(item); setOpen(false); }}><Text style={s.optionText}>{item || 'All suppliers'}</Text></Pressable>)}</ScrollView> : <Text style={s.emptyText}>No matching option</Text>}</Pressable></Pressable></Modal></View>; }

function MaterialForm({ record, visible, suppliers, materials, saving, onClose, onSave, onAddOption }: { record: MaterialRecord | null; visible: boolean; suppliers: string[]; materials: string[]; saving: boolean; onClose: () => void; onSave: (v: MaterialValues) => Promise<boolean>; onAddOption: (k: OptionKind, v: string) => Promise<void> }) { const [values, setValues] = useState<MaterialValues>({}); const [dateOpen, setDateOpen] = useState(false); const [choice, setChoice] = useState<OptionKind | null>(null); const [newOption, setNewOption] = useState(''); const [adding, setAdding] = useState(false); useEffect(() => { if (visible) setValues(record?.values || { date: inputDate(new Date()) }); }, [visible, record]); const set = (key: keyof MaterialValues, value: string) => setValues((old) => ({ ...old, [key]: value })); const add = async () => { if (!choice || !newOption.trim()) return; setAdding(true); try { await onAddOption(choice, newOption); set(choice === 'supplier' ? 'supplier' : 'material', newOption.trim()); setChoice(null); setNewOption(''); } finally { setAdding(false); } }; return <Modal visible={visible} animationType="slide" onRequestClose={onClose}><SafeAreaView style={s.formSafe}><View style={s.formHead}><View><Text style={s.eyebrow}>{record?.sheetRow ? `SHEET ROW ${record.sheetRow}` : 'NEW PURCHASE'}</Text><Text style={s.formTitle}>{record?.sheetRow ? 'Edit material purchase' : 'Add material purchase'}</Text></View><Pressable onPress={onClose}><Text style={s.close}>×</Text></Pressable></View><ScrollView contentContainerStyle={s.formScroll}><Text style={s.required}>Date and supplier are required. Total paid is calculated in the sheet.</Text>{Platform.OS === 'web' ? <View style={s.field}><Text style={s.controlLabel}>Date</Text><TextInput style={s.input} value={dateOnly(values.date)} onChangeText={(v) => set('date', v)} placeholder="YYYY-MM-DD" placeholderTextColor={c.muted} {...({ type: 'date' } as any)} /></View> : <FormField label="Date" value={dateOnly(values.date)} onPress={() => setDateOpen(true)} />}<ChoiceField label="Supplier *" value={String(values.supplier || '')} options={suppliers} onPick={(v) => set('supplier', v)} onAdd={() => setChoice('supplier')} /><FormField label="Bill no." value={String(values.billNo || '')} onChange={(v) => set('billNo', v)} keyboard="numeric" /><ChoiceField label="Material" value={String(values.material || '')} options={materials} onPick={(v) => set('material', v)} onAdd={() => setChoice('material')} /><View style={s.formTwo}><FormField label="Bill amount" value={String(values.billAmount || '')} onChange={(v) => set('billAmount', v)} keyboard="decimal-pad" /><FormField label="Without bill amount" value={String(values.withoutBillAmount || '')} onChange={(v) => set('withoutBillAmount', v)} keyboard="decimal-pad" /></View><View style={s.formTwo}><FormField label="Bill paid" value={String(values.billPaid || '')} onChange={(v) => set('billPaid', v)} keyboard="decimal-pad" /><FormField label="Without paid" value={String(values.withoutPaid || '')} onChange={(v) => set('withoutPaid', v)} keyboard="decimal-pad" /></View><View style={s.totalNote}><Text style={s.totalNoteLabel}>Total paid</Text><Text style={s.totalNoteValue}>Saved as Bill paid + Without paid by the sheet formula</Text></View><Pressable disabled={saving} onPress={() => onSave(values)} style={[s.primary, saving && s.disabled]}><Text style={s.primaryText}>{saving ? 'Saving to Google Sheets…' : 'Save purchase'}</Text></Pressable></ScrollView>{dateOpen && <Modal transparent animationType="fade"><View style={s.overlay}><View style={s.datePicker}><DateTimePicker value={new Date(`${dateOnly(values.date) || inputDate(new Date())}T12:00:00`)} mode="date" display={Platform.OS === 'ios' ? 'inline' : 'calendar'} onChange={(_, date) => { if (date) set('date', inputDate(date)); if (Platform.OS !== 'ios') setDateOpen(false); }} /><Pressable style={s.primary} onPress={() => setDateOpen(false)}><Text style={s.primaryText}>Done</Text></Pressable></View></View></Modal>}{choice && <Modal transparent animationType="fade"><View style={s.overlay}><View style={s.datePicker}><Text style={s.pickerTitle}>Add {choice}</Text><TextInput style={s.search} value={newOption} onChangeText={setNewOption} placeholder={`New ${choice} name`} placeholderTextColor={c.muted} autoFocus /><Pressable disabled={adding} style={[s.primary, adding && s.disabled]} onPress={add}><Text style={s.primaryText}>{adding ? 'Adding…' : 'Add to Google Sheet'}</Text></Pressable><Pressable style={s.cancel} onPress={() => setChoice(null)}><Text style={s.cancelText}>Cancel</Text></Pressable></View></View></Modal>}</SafeAreaView></Modal>; }

function FormField({ label, value, onChange, onPress, keyboard }: { label: string; value: string; onChange?: (v: string) => void; onPress?: () => void; keyboard?: 'numeric' | 'decimal-pad' }) { return <View style={s.field}><Text style={s.controlLabel}>{label}</Text>{onPress ? <Pressable style={s.input} onPress={onPress}><Text style={s.inputText}>{value || 'Select date'}</Text></Pressable> : <TextInput style={s.input} value={value} onChangeText={onChange} keyboardType={keyboard} placeholder="—" placeholderTextColor={c.muted} />}</View>; }
function ChoiceField({ label, value, options, onPick, onAdd }: { label: string; value: string; options: string[]; onPick: (x: string) => void; onAdd: () => void }) { const [open, setOpen] = useState(false); const [query, setQuery] = useState(''); const filtered = options.filter((x) => x.toLowerCase().includes(query.toLowerCase())); return <View style={s.field}><Text style={s.controlLabel}>{label}</Text><Pressable style={s.select} onPress={() => { setQuery(''); setOpen(true); }}><Text style={s.selectText}>{value || `Select ${label.replace(' *', '')}`}</Text><Text style={s.chevron}>⌄</Text></Pressable><Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}><Pressable style={s.overlay} onPress={() => setOpen(false)}><Pressable style={s.picker} onPress={(e) => e.stopPropagation()}><Text style={s.pickerTitle}>{label.replace(' *', '')}</Text><TextInput value={query} onChangeText={setQuery} style={s.search} placeholder="Search…" placeholderTextColor={c.muted} autoFocus /><ScrollView style={s.options}>{filtered.map((item) => <Pressable key={item} style={s.option} onPress={() => { onPick(item); setOpen(false); }}><Text style={s.optionText}>{item}</Text></Pressable>)}</ScrollView><Pressable style={s.addOption} onPress={() => { setOpen(false); onAdd(); }}><Text style={s.addOptionText}>＋ Add new</Text></Pressable></Pressable></Pressable></Modal></View>; }

function MaterialNav({ active, onChange }: { active: Tab; onChange: (x: Tab) => void }) { const tabs: { id: Tab; label: string }[] = [{ id: 'data', label: 'Purchase data' }, { id: 'summary', label: 'Summary' }, { id: 'ledger', label: 'Party ledger' }, { id: 'dashboard', label: 'Dashboard' }]; return <View style={s.nav}>{tabs.map((tab) => <Pressable key={tab.id} onPress={() => onChange(tab.id)} style={s.navItem}><MaterialNavIcon name={tab.id} active={active === tab.id} /><Text numberOfLines={1} style={[s.navText, active === tab.id && s.navTextActive]}>{tab.label}</Text></Pressable>)}</View>; } function MaterialNavIcon({ name, active }: { name: Tab; active: boolean }) { const color = active ? c.blue : c.muted; const common = { stroke: color, strokeWidth: 1.9, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }; if (name === 'data') return <Svg width={23} height={25} viewBox="0 0 24 24"><Rect x="3.5" y="4" width="17" height="16" rx="2.5" fill="none" {...common} /><Line x1="3.5" y1="9" x2="20.5" y2="9" {...common} /><Line x1="9.2" y1="9" x2="9.2" y2="20" {...common} /><Line x1="14.9" y1="9" x2="14.9" y2="20" {...common} /><Line x1="3.5" y1="14.5" x2="20.5" y2="14.5" {...common} /></Svg>; if (name === 'summary') return <Svg width={23} height={25} viewBox="0 0 24 24"><Line x1="4" y1="20" x2="20" y2="20" {...common} /><Rect x="5" y="12.5" width="3.4" height="6.5" rx="1" fill={color} /><Rect x="10.3" y="8.5" width="3.4" height="10.5" rx="1" fill={color} /><Rect x="15.6" y="4.5" width="3.4" height="14.5" rx="1" fill={color} /></Svg>; if (name === 'ledger') return <Svg width={23} height={25} viewBox="0 0 24 24"><Rect x="4.5" y="3.5" width="15" height="17" rx="2.5" fill="none" {...common} /><Line x1="8" y1="8" x2="16" y2="8" {...common} /><Line x1="8" y1="12" x2="16" y2="12" {...common} /><Line x1="8" y1="16" x2="13" y2="16" {...common} /><Path d="M7 3.5v17" fill="none" {...common} /></Svg>; return <Svg width={23} height={25} viewBox="0 0 24 24"><Circle cx="12" cy="12" r="8.5" fill="none" {...common} /><Path d="M12 3.5v8.5h8.5" fill="none" {...common} /><Path d="M12 12l-5.5 5.5" fill="none" {...common} /></Svg>; }

function materialPdf(groups: { supplier: string; rows: MaterialLedgerRow[]; overallRows?: MaterialLedgerRow[]; period?: string }[]) {
  return renderLedgerPdf('Material', groups.map((group) => ({
    party: group.supplier,
    period: group.period || 'All dates',
    rows: group.rows.map((row) => ({
      date: dateOnly(row.date),
      billNo: row.billNo,
      billAmount: Number(row.billAmount || 0),
      withoutBill: Number(row.withoutBill || 0),
      totalPurchase: Number(row.totalPurchase || 0),
      totalPaid: Number(row.totalPaid || 0),
      runningOutstanding: Number(row.runningOutstanding || 0),
    })),
    overallRows: (group.overallRows || group.rows).map((row) => ({
      date: dateOnly(row.date), billNo: row.billNo, billAmount: Number(row.billAmount || 0), withoutBill: Number(row.withoutBill || 0), totalPurchase: Number(row.totalPurchase || 0), totalPaid: Number(row.totalPaid || 0), runningOutstanding: Number(row.runningOutstanding || 0),
    })),
  })));
}

